fun {n} alpha v =>
  { utility := fun k j => if k = 0 then v j else v (OpposingTypes.reverseItem j),
    weight := fun k => if k = 0 then alpha else 1 - alpha }

fun {m n K} S reps =>
  { data := S, reduced := { utility := fun k j => S.model.utility (reps.repr k) j, weight := S.types.typeWeight },
    utility_agrees := ⋯, weight_eq_typeWeight := ⋯ }

fun {m n} [NeZero m] [NeZero n] W γ =>
  have base := W.optimalUserFairnessAtLevel 0;
  if h : base = 0 then 0 else (base - W.optimalUserFairnessAtLevel γ) / base

fun {m n} W ρ j =>
  have denom := W.itemNormalizer j;
  if h : denom = 0 then 0 else W.rawItemUtility ρ j / denom
